      "depends_on": [1]
    },
    {
      "id": 3,
      "claim": "No laptop model or manufacturer is listed in Fairtrade International’s certified‑product database.",
      "evidence": "A search of the publicly searchable Fairtrade International certified‑product database (accessed 2024‑07‑15) using keywords “laptop”, brand names (Dell, HP, Lenovo, Apple, ASUS, Acer, Framework) returns zero matches; Fairtrade International also states that electronics are not eligible for certification.",
